import * as fs from 'node:fs/promises'
export async function read(path: string) { return fs.readFile(path, 'utf8') }
export async function write(path: string, text: string) { await fs.writeFile(path, text) }
export async function mkdir(path: string) { await fs.mkdir(path, { recursive: true }) }
export async function remove(path: string) { await fs.rm(path, { recursive: true, force: true }) }
